<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait TrustedClientTenantAccessor
{
    private ?TrustedClientTenantVO $_tenant = null;
    public function getTenant(): ?TenantRef
    {
        return $this->_tenant?->value();
    }
    public function tenant(): ?TrustedClientTenantVO
    {
        return $this->_tenant;
    }
    public function isTenantChanged(?self $original = null): bool
    {
        return null !== $this->_tenant && !$this->_tenant->equals($original?->_tenant);
    }
    public function withTenant(TrustedClientTenantVO|TenantRef|null $tenant): self
    {
        $copy = clone $this;
        $copy->_tenant = TrustedClientTenantVO::from($tenant);
        return $copy;
    }
}
